mapper.select:
SELECT p.id AS post_id, p.title AS title, p.content AS content, p.member_id AS author_id, m.nickname AS author_nickname, p.status AS status, (SELECT COUNT(*) FROM community_report r WHERE r.target_type = 'POST' AND r.target_id = p.id AND r.reviewed_at IS NULL) AS report_count, p.updated_at AS status_changed_at FROM community_post p JOIN member m ON m.id = p.member_id WHERE p.status = #{status}
ORDER BY p.updated_at DESC, p.id DESC
ORDER BY EXISTS (SELECT 1 FROM community_report r WHERE r.target_type = 'POST' AND r.target_id = p.id AND r.reviewed_at IS NULL AND r.reason = 'MONEY_SCAM') DESC, p.updated_at ASC, p.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT c.id AS comment_id, c.post_id AS post_id, cp.status AS post_status, c.content AS content, c.member_id AS author_id, m.nickname AS author_nickname, c.status AS status, (SELECT COUNT(*) FROM community_report r WHERE r.target_type = 'COMMENT' AND r.target_id = c.id AND r.reviewed_at IS NULL) AS report_count, c.updated_at AS status_changed_at FROM community_comment c JOIN member m ON m.id = c.member_id JOIN community_post cp ON cp.id = c.post_id WHERE c.status = #{status}
ORDER BY c.updated_at DESC, c.id DESC
ORDER BY EXISTS (SELECT 1 FROM community_report r WHERE r.target_type = 'COMMENT' AND r.target_id = c.id AND r.reviewed_at IS NULL AND r.reason = 'MONEY_SCAM') DESC, c.updated_at ASC, c.id ASC
LIMIT #{limit} OFFSET #{offset}
